import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) throws Exception {
        System.out.print(new StringTokenizer(new String(System.in.readAllBytes())) instanceof StringTokenizer tk && Integer.valueOf(tk.nextToken()) instanceof Integer n && Integer.valueOf(tk.nextToken()) instanceof Integer m && Integer.valueOf(tk.nextToken()) instanceof Integer c && IntStream.generate(() -> Integer.parseInt(tk.nextToken())).limit(n).toArray() instanceof int[] x && IntStream.generate(() -> Integer.parseInt(tk.nextToken())).limit(n - 1).toArray() instanceof int[] p && Integer.valueOf(Integer.highestOneBit(Math.max(n - 1, 1) * 2 - 1)) instanceof Integer sz && new long[2 * sz][] instanceof long[][] t && ((BinaryOperator<long[]>) (u, w) -> new long[]{u[0] + w[0], Math.max(u[1], u[0] + w[1]), Math.max(w[2], w[0] + u[2]), Math.max(Math.max(u[3], w[3]), u[2] + w[1])}) instanceof BinaryOperator<long[]> mg && IntStream.range(0, sz).allMatch(i -> (t[sz + i] = i < n - 1 ? new long[]{100L * (x[i + 1] - x[i]) - 2L * c * p[i], Math.max(0, 100L * (x[i + 1] - x[i]) - 2L * c * p[i]), Math.max(0, 100L * (x[i + 1] - x[i]) - 2L * c * p[i]), Math.max(0, 100L * (x[i + 1] - x[i]) - 2L * c * p[i])} : new long[4]) != null) && IntStream.iterate(sz - 1, i -> i >= 1, i -> i - 1).allMatch(i -> (t[i] = mg.apply(t[2 * i], t[2 * i + 1])) != null)&& IntStream.generate(() -> Integer.parseInt(tk.nextToken())).limit(2L * m).toArray() instanceof int[] qs ? String.format(Locale.US, "%.9f", IntStream.range(0, m).parallel().mapToDouble(q -> Optional.of(qs[2 * q]).map(a -> Optional.of(qs[2 * q + 1]).map(b -> (double) Stream.iterate(new long[][]{{a - 1 + sz, b - 1 + sz}, new long[4], new long[4]}, st -> new long[][]{{(st[0][0] + (st[0][0] & 1)) >> 1, (st[0][1] - (st[0][1] & 1)) >> 1}, (st[0][0] & 1) == 1 ? mg.apply(st[1], t[(int) st[0][0]]) : st[1], (st[0][1] & 1) == 1 ? mg.apply(t[(int) st[0][1] - 1], st[2]) : st[2]}).filter(st -> st[0][0] >= st[0][1]).findFirst().map(st -> mg.apply(st[1], st[2])[3]).get()).get()).get()).sum() / 200.0) : "");
    }
}

